) AS (
  VALUES 
    (1022::BIGINT, 'Si acaso el mejor profesor del Tec. Una maravilla tanto como persona como profesor. Prepárense para leer mucho, pero sintetiza las cosas de forma que se entiende. En las clases se expone bastante. Con un buen grupo de trabajo bien bien se puede pasar con 100.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Muchos proyectos grupales']::TEXT[], '2025-12-19T00:00:00+00:00'::TIMESTAMPTZ, '8f76fa19cc348b70febbda36d9aa7b286fd9bfc2bbb09c1d11dd73b672a8bbde'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es un profesor excelente, si usted tiene alguna situación es muy flexible y brinda apoyo, las clases aveces son largas pero suelen ser dinámicas y entretenidas, el curso se pasa fácil y se aprende bastante pero asegurese de tener un buen grupo de trabajo, hay que leer bastante y exponer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'dbbddf30e0021ce897ff66f85826a03b5509b7a1c718a3f65f2abf7d8c302282'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es muy claro con las clases, son dinámicas y se trabaja mucho en grupos. El curso se pasa casi que solo con tener un buen equipo de trabajo donde todos colaboren y hagan bien la parte que les corresponde. Todas las semanas se hacen tareas y se hace alguna presentación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, '6b2f5f9701327583494234262bc869b86fe35672454cbd8a23b8aeadf3c117da'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Mi profe favorito de toda la carrera. Es un rayito de sol y brinda mucho apoyo, siempre esta ahi para ayudar. Eso si, sus clases son muy largas y tenes que preparte para leer MUCHO. En todoas sus lecciones hay que pasar a presnetar algo y mucho trabajo en grupo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '6d91034de577ee803d462d41e221f527b0598c8f20477deae1fb83662ab7e52f'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'El profesor es muy buena gente y explica demasiado claro. Si deja tareas todas las semanas pero son sencillas de hacer si se escoge un buen grupo de trabajo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '7723480b1059211927d7b6d6f7bcd720b05f883249f0b1700511bfc0dcbb76db'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es el mejor profe que me he topado en la vida. La manera de enseñar es super clara y hace actividades para que los estudiantes entiendan. Un 10/10 Lo súper recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-15T00:00:00+00:00'::TIMESTAMPTZ, '8362ae41d17a031b84400096854c1e2043bb523c9a63758750a96bd8fa0e4808'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es muy buen profesor, realmente busca hacer que las clases sean dinámicas. Si es importante tener un buen grupo de trabajo porque todas las tareas son grupales. Se deben de realizar muchas exposiciones, pero brinda un ambiente cómodo. Muy compresivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'b65e7401e49b6676ee1aaf5886bbbdd1d6396e76a90d75c2b6282aaaa59e9841'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'El mejor profe del mundo. Sus clases son muy dinámicas, largas pero entretenidas. Hay muchas tareas, se vuelve cansado, pero con un buen equipo todo sale bien. Es muy accesible, siempre contesta tus dudas y esta dispuesto a ayudar. Es muy inteligente, aprovechen todo su conocimiento.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Respetado por los estudiantes']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '01469350274c9c0e719aa9c87a3bde49cd9e5f5e043fb02028588795d7a847f5'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'De los mejores profes que he tenido. Es súper ordenado, amable, dedicado. Deja tareas todas las clases pero son de mucha ayuda para aprender. Haganse de un buen grupo de trabajo. Más profes como él en el mundo :) Súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'f501a63d5c8c47eae6a5cd7213b7452404515902de5fcb0534f198cd54755322'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es un excelente profesor, realmente le apasiona la enseñanza, toma en cuenta la opinión de los estudiantes y da buen retroalimentación. Todo lo leído se refuerza en clase y las tareas ayudan al aprendizaje verdaderamente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2022-01-07T00:00:00+00:00'::TIMESTAMPTZ, '2ded77718d6d9b3ad86af3a23b60013b1d76263eb1445a3017a6cfa9c58fb280'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Excelente profe. Uno de los mejores que he tenido. Explica súper claro y siempre está atento a dudas. Los exámenes son muy prácticos, deja tarea todas las semanas, pero ayudan mucho a entender el contenido. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '08ca04986a3daaa21bd42c25c9a67629a840595b46afa48b347ac948bdb7b8f0'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Excelente profe. Se hacen tareas semanales grupales e individuales, a veces un poquito largas, pero aportan mucho al aprendizaje y no son difíciles. Lo recomiendo 100%.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Inspirador']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '0cb5733c2aaa7559d3d32caf08f73838a8f832050a92819bfbcb75c5dd133a53'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'De los mejores profes. Es SÚPER organizado, siempre da una retroalimentación muy buena de todas las tareas semanales y trabajos. Es muy comprensivo y flexible, y siempre se preocupa porque en realidad la materia quede clara. Si tienen la oportunidad de matricular con él, háganlo sin miedo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '55dee60507eb908f7d1c41126e3f2d9a8eab1f34a4cabf0e708e0418930695ca'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Un excelente profesor. El mejor de la carrera sin duda. Muy amable y comprensivo. Las tareas son semanales y son muy útiles para aprender la materia. Los examenes son sencillos. Da muy buena retroalimentación. 100% recomendado. Es la mejor opción para cualquier curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '6a6422d237b8592132c5f352956c42b462c8eaa8e2cf709a71dda8d4d5427f76'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Es un excelente profe, de los mejores he tenido hasta ahorita. Siempre da feedback y es súper buena gente. Hay tareas todas las semanas, pero son sencillas y ayudan a que uno entienda la teoría. Si tiene la oportunidad, matricule con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-01T00:00:00+00:00'::TIMESTAMPTZ, '43628dfa4e118f81052d0074d8657003ea80c167fe8f429df81688409dbf0a36'::TEXT, ARRAY[2442]::BIGINT[]),
    (1022::BIGINT, 'Muy bueno, explica súper bien. En la virtual se acopló muy biiien. A veces si es un poquitillo intenso con las tareas pero nada muy difícil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-28T00:00:00+00:00'::TIMESTAMPTZ, '7b9da2e046bfbcb0feebbe4570d71d04ab51ddaf9f6375a6f8cc58d1cf596870'::TEXT, ARRAY[2419]::BIGINT[]),
    (1022::BIGINT, 'Un profesor excelente. Conoce mucho la materia y la enseña muy bien. Las clases no son pesadas y es muy dinámico. Todos los trabajos te ayudan a aprender y la vas a pasar muy bien con él. Los exámenes requieren que adquieras conocimiento. Tiene muy buenos gustos musicales. Recomendado al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'ea7a37de5d85a1eb79bb8fcd8e62fdd56293d5410b892f9606cc7de28ac037de'::TEXT, ARRAY[2419]::BIGINT[]),
    (1022::BIGINT, 'Es el mejor profesor que he tenido en toda la carrera. Explica muy bien. Se adapta a las nuevas situaciones. Muy inteligente, sabe demasiado y es muy buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'd183f90d8aeb2de669d12f8643eae210c804517f2cdfa1f28fdf0f92c6002b59'::TEXT, ARRAY[2419]::BIGINT[]),
    (1022::BIGINT, 'Es excelente! Se enfoca que el estudiante comprenda y pueda ser capaz de realizar cada proceso del curso. Muchas tareas grupales/individuales que te ayudan a comprender mucho los temas y no debas estudiar tanto para el examen. Principal enfoque en el proyecto y crear herramientas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'd7622a657b1cad483bd6e645c5bc4e5cef358805b8660698ffd1858dc1160b3b'::TEXT, ARRAY[2419]::BIGINT[]),
    (1022::BIGINT, 'Excelente profesor, de los mejores en el TEC, se aprende bastante, las tareas lo preparan bastante para las evaluaciones, un profesor recomendado al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd52ea6375c8af0bd2bd98f39d779c73a3122589749b878d2e94470ffe68c171d'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-06T00:00:00+00:00'::TIMESTAMPTZ, '76e55bf096023cdb4261a7c08d227344e1964a28624568e648af7fe8ee42aa77'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'De los mejores profes del TEC, si puede meter algo con él hagalo. Se aprende bastante y se le agarra gusto a la carrera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '05ad780bd210024f125acb2bef23d51d9659f874ab450f97119c55a9c70f8c4c'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (1022::BIGINT, 'Muy bueno, las clases son dinámicas, busca que el estudiante aprenda, trabajos fáciles que ayudan mucho. Muy amigable, los exámenes son fáciles y a la vez duros por la cantidad de puntos ya que son muy pocos. No lo piense dos veces, el mejor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'ce76717917946865322f862a1f985afb6f4790198fec7c1a1b311fd1d62ed7db'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'Nada más si tiene la oportunidad, matricule con él. Él mejor profe. Las clases super dinámicas, los exámenes muy fáciles. Te ayuda un montón en el proyecto final y quiere sacar ese espíritu emprendedor del estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2018-01-11T00:00:00+00:00'::TIMESTAMPTZ, '5901f151e1b3279ed007a90b68df589fbbf7c681bd7eeeb37a298cfc1803731a'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'Es el MEJOR profesor. Hay que hacer varios trabajos pero no son complicados, es muy dinámico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-19T00:00:00+00:00'::TIMESTAMPTZ, '4de9c7edd5b84588e7583163b0b8eabd03918b64d108617b2dd768128813e56f'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'Es el mejor profe que he tenido hasta el momento. Realmente es inspirador y la asistencia no se vuelve obligatoria :) Si se me presenta la oportunidad, volvería a tomar cualquier curso con el. Ademas, es excelente apoyo en los proyectos de negocios.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'f9eff0e3fd577b6c2a7ec5c81974250065d20a275ad2e1cd967b509b84002947'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'El mejor profesor que he tenido. Exige excelencia, pero uno ni lo siente porque aprende sin darse cuenta. Hace que las clases sean súper entretenidas e interesantes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3349cef9c9ade461d60f5c2b5c1c9080e4ce8101ee040e01ca41961a36453287'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (1022::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd87ebb18ea029c2a41e999d05d0704ee1b36b50281489ef9f71032f93abe01ce'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'El mejor profesor definitivamente! Las clases son muy dinámicas y se aprende un montón. 100% Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-12T00:00:00+00:00'::TIMESTAMPTZ, '64078a5c139495bbb9119a10c990f163e7b90c4865952fdced469865577cfd23'::TEXT, ARRAY[2363]::BIGINT[]),
    (1022::BIGINT, 'Excelente profesor, súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '239cecc5060b4913e0aa2f9f4113d82036297d2c061e13e138c32cd61b71cbbd'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (1022::BIGINT, 'Muy buen profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'fdcb9402e1cafb9287898eb233d0e6695126264e8ad43e2902a83ef9dcf14a92'::TEXT, ARRAY[965]::BIGINT[]),
    (1022::BIGINT, 'Exc profesor de verdad sabe de lo que habla, explica super bien la clase es cero aburrida, super recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '9e1cddffb905ccf53579251dc361c9f5da30e4d3b67c1788da59b8d578c8637e'::TEXT, ARRAY[2359]::BIGINT[]),
    (1022::BIGINT, 'Definitivamente ama su trabajo y sabe lo que hace.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, '61b971a873307c65b008e8fad204546c724bdd878ef0c6688bb6fdbe74a3d205'::TEXT, ARRAY[2419]::BIGINT[]),
    (1022::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '612b657549eea4ed742e3ce86ba5e7681075b95665093883a141d0515730eb8d'::TEXT, ARRAY[98, 2363, 2359, 96]::BIGINT[]),
    (1022::BIGINT, 'Es el mejor profesor, se aprende demasiado, y se nota que ama la carrera'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '77697282edf6f3732a78be1ecdde6c1a1ac2c637a03949381fbd63dd80b77a5a'::TEXT, ARRAY[2359]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
